struct fast_io{

  fast_io(){ios_base::sync_with_stdio(false); cin.tie(nullptr); cout << fixed << setprecision(20);}

} fast_io_;



template <class Monoid>

class SegmentTree{

  public:

    int n;

    using T = typename Monoid::value_type;

    vector<T> val;

    T identity;



    SegmentTree(){}

    SegmentTree(int n_, vector<T> v=vector<T>()){

      n = 1;

      while(n < n_)n *= 2;

      identity = Monoid::identity;

      val.assign(2*n-1, identity);



      for(size_t i = 0; i < v.size(); i++){

        val[i+n-1] = v[i];

      }

      for(int i = n - 2; i >= 0; i--){

        val[i] = Monoid::operation(val[2*i+1], val[2*i+2]);

      }

    }

    void update(int k, const T &t){

      k = k + n - 1;

      val[k] = t;

      while(k > 0){

        k = (k - 1) / 2;

        val[k] = Monoid::operation(val[2*k+1], val[2*k+2]);

      }

    }

    T query(int a, int b, int k, int l, int r){

      if(r <= a || b <= l)return identity;

      if(a <= l && r <= b)return val[k];

      T lv = query(a, b, 2*k+1, l, (l+r)/2);

      T rv = query(a, b, 2*k+2, (l+r)/2, r);

      return Monoid::operation(lv, rv);

    }

    T query(int a, int b){

      return query(a, b, 0, 0, n);

    }

    T get(int i){

      return val[i+n-1];

    }

};



template <typename T>

class RSQ{

  public:

    const static T identity = 0;

    using value_type = T;



    RSQ(){}

    static T operation(T &l, T &r){

      return (l + r) % mod;

    }

};



ll dp[1000100];



int main(int argc, char const* argv[])

{

  int n; cin >> n;

  SegmentTree<RSQ<ll>> seg(n);

  dp[n-1] = n;

  seg.update(n - 1, n);

  for(int i = n - 2; i >= 0; i--){

    dp[i] = (ll)(n - 1) * (ll)(n - 1) % mod;

    (dp[i] += dp[i+1]) %= mod;

    if(i + 3 < n)(dp[i] += seg.query(i + 3, n)) %= mod;

    int r = i + 2;

    if(n - i - 1 == 1)r--;

    (dp[i] += r) %= mod;

    seg.update(i, dp[i]);

  }

  cout << dp[0] << endl;

  return 0;

}

