#include <iostream>
#include <vector>
#include <algorithm>

std::vector<int> v;
std::vector<int> best;
int k;
const int INF = 999999999;

int solve(int x) {
    if (x < 0) {
        return INF;
    }

    if (x <= k) {
        return std::abs(v[0] - v[x]);
    }

    if (best[x] == -1) {
        int mina = INF;
        for (int i = 1; i <= k; ++i) {
            int score = solve(x - i) + std::abs(v[x] - v[x - i]);
            mina = std::min(mina, score);
        }
        best[x] = mina;
    }

    return best[x];
}

int main() {
    int n;
    std::cin >> n >> k;

    v.resize(n);
    best.assign(n, -1);

    for (int i = 0; i < n; ++i) {
        std::cin >> v[i];
    }

    std::cout << solve(n - 1);

    return 0;
}

