	cin >> N >> K;

	H.resize(N + 1);

	for (int i = 1; i <= N; ++i)

		cin >> H[i];

	dp.resize(N + 1, INF);

	dp[1] = 0;

	dp[2] = abs(H[2] - H[1]);

