using namespace std;
using TUP = tuple<int, int, int, int>;
using VD = vector<double>;
using VVD = vector<VD>;
using VVVD = vector<VVD>;
int n;
VVVD memo; //ijk -> 000 となる期待値
void dfs(int n1, int n2, int n3) {
	if (memo[n1][n2][n3] != 0) {
		return;
	}
	if (n1 == 0 && n2 == 0 && n3 == 0) {
		// 0,0,0の値は0で初期化済み
		return;
	}
	if (n1 > 0) { dfs(n1-1, n2, n3); }
	if (n2 > 0) { dfs(n1+1, n2-1, n3); }
	if (n3 > 0) { dfs(n1, n2+1, n3-1); }
	double val = n;
	if (n1 > 0) { val += memo[n1-1][n2][n3] * n1; }
	if (n2 > 0) { val += memo[n1+1][n2-1][n3] * n2; }
	if (n3 > 0) { val += memo[n1][n2+1][n3-1] * n3; }
	val /= (n1 + n2 + n3);
	memo[n1][n2][n3] = val;
}
int main() {
	cin >> n;
	int a;
	int n1, n2, n3;
	n1 = n2 = n3 = 0;
	for (int i = 0; i < n; i++) {
		cin >> a;
		switch (a) {
			case 1: n1++; break;
			case 2: n2++; break;
			case 3: n3++; break;
			default: break;
		}
	}
	memo.assign(n+1, VVD(n+1, VD(n+1, 0)));
	dfs(n1, n2, n3);
	printf("%.12f\n", memo[n1][n2][n3]);
	return 0;
}

