#include<bits/stdc++.h>

#include<vector>

#define LL long long

#define PI pair<LL,LL>

using namespace std;

LL D,St1[25],St2[25],P[25];

vector<LL>V;

void DFS(LL L,LL R,vector<PI>& Rec,LL Val,LL Cnt){

	if(L==R){

		Rec.push_back(PI(Val,Cnt));

		return; 

	}

	for(LL I=-9;I<=9;I++) DFS(L+1,R,Rec,Val+I*V[L],Cnt*(L==0?St2[I+10]:St1[I+10]));

}

LL Solve(LL Len){

	V.clear();

	for(LL I=0;Len-I-1>I;++I) V.push_back(P[Len-I-1]-P[I]);

	vector<PI>An1,An2;

	LL Res=0;

	DFS(0,(V.size()+1)/2,An1,0,1);

	DFS((V.size()+1)/2,V.size(),An2,0,1);

	map<LL,LL>Mp;  

	for(LL I=0;I<An2.size();I++) Mp[An2[I].first]+=An2[I].second;

	for(LL I=0;I<An1.size();I++) Res+=Mp[D+An1[I].first]*An1[I].second;

	if(Len&1) Res*=10;

	return Res;

