                a.push_back(i);
            }
        }

        for (int m = 1; m < (1 << a.size()); m++) {
            int nmask = 0;
            for (int i = 0; i < a.size(); i++) {
                if ((m >> i) & 1) {
                    nmask += 1 << a[i];
                }
            }
