		if (d == 'R') R.emplace_back(xy);

		if (d == 'L') L.emplace_back(xy);

		if (d == 'U') U.emplace_back(xy);

		if (d == 'D') D.emplace_back(xy);

	}

	sort(R.begin(), R.end(), [](auto l, auto r) {return l.x < r.x; });

	sort(L.begin(), L.end(), [](auto l, auto r) {return l.x < r.x; });

	sort(U.begin(), U.end(), [](auto l, auto r) {return l.x < r.x; });

	sort(D.begin(), D.end(), [](auto l, auto r) {return l.x < r.x; });



	lint ans = LINF;

	auto update = [&ans](auto &l, auto &r, pnt grad, int speed) {



		map<lint, vector<lint>> lmap, rmap;

		for (const auto& xy : l) lmap[xy * grad].emplace_back(xy.x);

