				}

			}

		}



	};



	update(R, U, pnt(1, 1), 10);

	update(D, L, pnt(1, 1), 10);

	update(R, D, pnt(1, -1), 10);

	update(U, L, pnt(1, -1), 10);

	update(R, L, pnt(0, 1), 5);



	for (auto& e : U) swap(e.x, e.y);

