	sort(D.begin(), D.end(), [](auto l, auto r) {return l.x < r.x; });

	update(U, D, pnt(0, 1), 5);



	if (ans == LINF) cout << "SAFE" << "\n";

	else cout << ans << "\n";



	return 0;

}

