// Frog 2 https://atcoder.jp/contests/dp/tasks/dp_b

#include <bits/stdc++.h>

using namespace std;



const int INF = 1e9 + 5;



int n, k;

vector<int> h;

vector<int> memo;

vector<bool> computed;



// rec(x) is best score to get to position x

int rec(int pos) {

	if(pos == 0) {

		return 0;

	}

	if(computed[pos]) {

		return memo[pos];

	}

	int best = INF;

	for(int jump = 1; jump <= k && pos - jump >= 0; ++jump) {

		best = min(best, rec(pos - jump) + abs(h[pos] - h[pos-jump]));

	}

	computed[pos] = true;

	return memo[pos] = best;

}



int solve1() {

	return rec(n-1);

}



int solve2() {

	vector<int> dp(n, INF);

	dp[0] = 0;

	for(int i = 1; i < n; i++) {

		for(int jump = 1; jump <= k && i - jump >= 0; ++jump) {

			dp[i] = min(dp[i], dp[i-jump] + abs(h[i]-h[i-jump]));

		}

	}

	return dp[n-1];

}



int main() {

	cin >> n >> k;

	h.resize(n);

	memo.resize(n, 0);

	computed.resize(n, false);

	for(int& x : h) {

		cin >> x;

	}

	cout << solve2();

}

