  int N;

  string S;

  cin >> N >> S;



  if (N < 3) {

    cout << 0 << endl;

    return 0;

  }



  map<char, vector<int> > counts;

  counts['R'] = vector<int>(N);

  counts['G'] = vector<int>(N);

  counts['B'] = vector<int>(N);



  counts['R'][N - 1] = 0;

  counts['G'][N - 1] = 0;

  counts['B'][N - 1] = 0;

  counts[S[N - 1]][N - 1]++;



