int min(int a, int b) {

  if (a < b) return a;

  else return b;

}

int ze(int a) {

  if (a > 0) return a;

  else return -a;

}

int main () {

  int N, K;

  cin >> N >> K;

  K = min(N, K);

  int h[100004];

  for (int i = 0; i < N; i ++) {

    cin >> h[i];

  }

  int cost[100004];

  cost[1] = 0;

  cost[2] = ze(h[1] - h[0]);

  if (N == 2) {

    cout << cost[2] << endl;

    return 0;

  }

  int k = cost[2] + ze(h[2] - h[1]);

  int j;

  if (K > 1) {

    j = ze(h[2] - h[0]); 

  }

  else j = 10000000;

  cost[3] = min(k, j);

  if (N == 3) {

    cout << cost[3] << endl;

    return 0;

  }

  for (int i = 4; i <= N; i ++) {

    long int m = 1000002000;

    for (int l = 1; l <= K; l ++) {

      if (l > i - 1) break;

      int p = cost[i - l] + ze(h[i -1] - h[i - l - 1]);

      if (m > p) m = p;

    }

    cost[i] = m;

  }

  cout << cost[N] << endl;

}

