  vector<int>dp(N);

  for (int i = 0; i <= K; i ++) {

    dp[i] = sa(he[0], he[i]);

  }

  for (int i = K + 1; i < N; i ++) {

    dp[i] = sa(he[i], he[i - 1]) + dp[i - 1];

    for (int j = 2; j <= K; j ++) {

      int kuma = sa(he[i], he[i - j]) + dp[i - j];

      if (dp[i] > kuma) dp[i] = kuma;

    }

