int n, k;
int a[100005];
int dp[100005];
int solve(int ind)
{
	if (ind >= n)//No of ways to reach last step when we are at last step
	{
		return 0;
	}
	if (dp[ind] != -1)
	{
		return dp[ind];
	}
	int val;
	for (int i = ind + 1; i <= min(n, ind + k); i++)
	{
		val = min(val, abs(a[ind] - a[i]) + solve(i));
	}
	return dp[ind] = val;
}
