    int n;
    string s;
    cin >> n >> s;

    vector<int> countR(n), countG(n), countB(n);

    for (int i = n - 1; i >= 0; i--) {
        if (i < n - 1) {
            countR[i] = countR[i + 1];
            countG[i] = countG[i + 1];
            countB[i] = countB[i + 1];
        }

        if (s[i] == 'R') countR[i]++;
        else if (s[i] == 'G') countG[i]++;
        else if (s[i] == 'B') countB[i]++;
    }

