using namespace std;

const int MAXN = 301;
int v[4];
double n;
double dp[MAXN][MAXN][MAXN];

double f(int a, int b, int c) {
    if (dp[a][b][c] >= 0) return dp[a][b][c];

    double res = 0;

    if (a) res += (double)a / (a + b + c) * f(a - 1, b, c);
    if (b) res += (double)b / (a + b + c) * f(a + 1, b - 1, c);
    if (c) res += (double)c / (a + b + c) * f(a, b + 1, c - 1);

    double z = n - a - b - c;
    res += (1 - z / n) / ((1 - z / n) * (1 - z / n));

    return dp[a][b][c] = res;
}

