    cin >> n;

    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        v[x]++;
    }

    for (int i = 0; i < MAXN; i++) {
        for (int j = 0; j < MAXN; j++) {
            for (int k = 0; k < MAXN; k++) {
                dp[i][j][k] = -1;
            }
        }
    }

    dp[0][0][0] = 0;

    cout << fixed << setprecision(12) << f(v[1], v[2], v[3]) << endl;

