using namespace std;



const int MAXV = 10000 + 16;

const int MAXE =  MAXV * 10;

const int INF = 0x3f3f3f3f;

typedef long long LL;

typedef pair<int, int> P; // 坐标点



int N, M;

int V, E;

struct Edge {

	int from, to;

	double cost;

	Edge(int _from=0, int _to=0, double _cost=0) :from(_from), to(_to), cost(_cost){}

};

P p[MAXV];

Edge edge[MAXE];

int father[MAXV];

int height[MAXV];

bool cmp(const Edge& a, const Edge& b) {

	return a.cost > b.cost;

}

void Init(int n) {

	for (int i = 0; i < n; ++i) {

		father[i] = i;

		height[i] = 0;

	}

}

int Find(int x) {

	if (father[x] == x)

		return x;

	else

		return father[x] = Find(father[x]);

}

void Unite(int x, int y) {

	x = Find(x);

	y = Find(y);

	if (x == y)

		return;

	if (height[x] < height[y]) {

		father[x] = y;

	} else {

		father[y] = x;

		if (height[x] == height[y])

			++height[x];

	}

}

bool same(int x, int y) {

	return Find(x) == Find(y);

}

double Kruskal() {

	Init(MAXV);

	sort(edge, edge + E, cmp);

	double res = 0;

	for (int i = 0; i < E; ++i) {

		Edge e = edge[i];

		if (!same(e.from, e.to)) {

			Unite(e.from, e.to);

		}

		else {

			res += e.cost;

		}

	}

	return res;

}

void solve() {

	double res = Kruskal();

	printf("%.3f\n", res);

}





