    if (dp[A][B][C] > 0.0) return dp[A][B][C];
    if (A == 0 && B == 0 && C == 0) return 0.0;

    double val = 0.0;
    double unit = 1.0 * N / (A + B + C);

    if (A > 0) {
        val += 1.0 * (unit + solve(A - 1, B + 1, C, dp)) * A / (A + B + C);
    }
    if (B > 0) {
        val += 1.0 * (unit + solve(A, B - 1, C + 1, dp)) * B / (A + B + C);
    }
    if (C > 0) {
        val += 1.0 * (unit + solve(A, B, C - 1, dp)) * C / (A + B + C);
    }

    dp[A][B][C] = val;
    return val;
}

