using namespace std;



typedef long long ll;



const int MAXN = 16;



int N;

ll a[MAXN][MAXN], group[1 << MAXN], dp[1 << MAXN];



int unpack(int mask, int popcount, int packed) {

    int result = 0;

    for (int i = 0; i < popcount; i++) {

        if (packed & (1 << i))

            result |= 1 << __builtin_ctz(mask);

        mask &= mask - 1;

    }

    return result;

}



ll score(int mask) {

    if (dp[mask] == -1) {

        dp[mask] = group[mask];

        int popcount = __builtin_popcount(mask);

        for (int packed = 1; packed < (1 << popcount); packed++) {

            int submask = unpack(mask, popcount, packed);

            if ((mask | submask) == mask)

                dp[mask] = max(dp[mask], group[submask] + score(mask & ~submask));

        }

    }

    return dp[mask];

}



int main() {

    ios_base::sync_with_stdio(false);

    cin.tie(nullptr);

    cin >> N;

    for (int i = 0; i < N; i++)

        for (int j = 0; j < N; j++)

            cin >> a[i][j];

    for (int mask = 0; mask < (1 << N); mask++)

        for (int i = 0; i < N; i++)

            for (int j = i + 1; j < N; j++)

                if ((mask & (1 << i)) && (mask & (1 << j)))

                    group[mask] += a[i][j];

    memset(dp, -1, sizeof dp);

    cout << score((1 << N) - 1) << endl;

}

