int solve(int i) {

	if(i==n) return 0;

	if(i>n) return inf;

	if(dp[i]!=-1) return dp[i];

	int mn = 2*inf;

	for(int j=1;j<=k;++j) {

		int a = solve(i+j) + abs(A[i]-A[i+j]);

