ここで、数列 ai が与えられるので、何回操作を行うことになるかを求めてください。
-----問題ここまで----- */
/* -----解説等-----
----解説ここまで---- */
LL N;
LL ans = 0LL;
int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);
	cin >> N;
	VL a(N);
	FOR(i, 0, N) {
		cin >> a[i];
	}
	int update = 1;
	while (update) {
		update = 0;
		FOR(i, 0, N) {
			LL ret = a[i] / N;
			if (ret) {
				a[i] -= ret*N;
				ans += ret;
				FOR(j, 0, N) {
					if (i == j)continue;
					a[j] += ret;
				}
			}
		}
		LL m = 0;
		FOR(i, 0, N) {
			m = max(m, a[i]);
		}
		if (m < N)update = 0;
		else update = 1;
	}
	cout << ans << "\n";
	return 0;
}

