#define LLINF 2000000000000000000LL //2e18

#define SIZE 100010



ll dp[13][1<<13][10]; //桁数, 現在のエレベーター,　前の桁 



bool solve(){

  int n;

  int low[7], up[7];



  scanf("%d", &n);

  if(n == 0) return false;



  for(int i=0;i<n;i++) scanf("%d%d", low+i, up+i);



  memset(dp, 0, sizeof(dp));



  dp[0][1][0] = 1;



  ll ans = 0;



  for(int i=0;i<n*2;i++){

    for(int j=0;j<(1<<(2*n));j++){

      for(int k=0;k<10;k++){

