          //1桁目

          if((1 << (l*2)) & j){

            for(int x=max(1,low[l]);x<=min(9, up[l]);x++)

              next[x] |= 1 << (l*2+2);

            for(int x=max(1,low[l]/10);x<=min(9,up[l]/10);x++)

