//最大公約数

int gcd(int x, int y){

  if(x % y == 0) return y;

  return gcd(y, x % y);

}

//最小公倍数

int lcm(int x, int y){

  return x * y / gcd(x, y);

}

//フィボナッチ数列

//配列dpを-1で初期化する

int fib(int n){

  if(n == 0 || n == 1) return dp[n] = 1;

  if(dp[n] != -1) return dp[n];

  return dp[n] = fib(n - 1) + fib(n - 2);

}

//階乗計算(factorial)

int fact(int n){

  if(n = 1) return 1;

  return n * fact(n - 1);

}

//累乗計算(Exponentiation)

//x**y

ll expo(int x, int y){

  ll ans = 1;

  rep(i, y){

    ans *= x;

  }

  return ans;

}

