                    flag = true;
                    p = i;
                }
            }

            if (flag) {
                div = a[p] / n;
                ans += div;
                a[p] %= n;
                for (int i = 1; i <= n; i++) {
                    if (i != p) {
                        a[i] += div;
                    }
                }
            }
        }

