vector<LL> f;
vector<LL> s;
vector<LL> sum;

LL read() {
    LL _ = 0, __ = 1;
    char ch;
    while (true) {
        ch = getchar();
        if (ch == '-' || (ch >= '0' && ch <= '9')) break;
    }
    if (ch == '-') __ = -1;
    else _ = ch - '0';
    while (true) {
        ch = getchar();
        if (ch < '0' || ch > '9') break;
        _ = _ * 10 + ch - '0';
    }
    return _ * __;
}

void pushup(LL rt) {
    sum[rt] = sum[rt << 1] + sum[rt << 1 | 1];
}

void build(LL l, LL r, LL rt) {
    sum[rt] = 0;
    if (l == r) return;
    LL m = (l + r) >> 1;
    build(l, m, rt << 1);
    build(m + 1, r, rt << 1 | 1);
    pushup(rt);
}

void update(LL x, LL l, LL r, LL rt) {
    if (l == r) {
        sum[rt] += 1;
        return;
    }
    LL m = (l + r) >> 1;
    if (x <= m) update(x, l, m, rt << 1);
    else update(x, m + 1, r, rt << 1 | 1);
    pushup(rt);
}

LL query(LL x, LL y, LL l, LL r, LL rt) {
    if (x > y) return 0;
    if (x <= l && y >= r) return sum[rt];
    LL set = 0;
    LL m = (l + r) >> 1;
    if (x <= m) set += query(x, y, l, m, rt << 1);
    if (y > m) set += query(x, y, m + 1, r, rt << 1 | 1);
    return set;
}

LL check(LL x) {
    sum.assign(n * 4, 0);
    ans = 0;
    maxx = -1;
    s.assign(n + 1, 0);

    for (int i = 1; i <= n; i++) {
        if (f[i] > x) s[i] = -1;
        else s[i] = 1;
        s[i] += s[i - 1];
    }

    for (int i = 0; i <= n; i++) {
        s[i] += n + 1;
        maxx = max(maxx, s[i]);
    }

    build(1, maxx + 5000, 1);

    for (int i = 0; i <= n; i++) {
