//! @brief Regard Map of {key, count} to record count of key, initialize with 0 if key not found, then add

//! adding to key's count.

template <typename Map, typename Value = typename Map::mapped_type>

Value &

MapAddCount(Map &map, typename Map::key_type key, Value adding)

{

    auto [it, flag] = map.try_emplace(key, 0);

    (void)flag;

    auto &count = it->second;

    count += adding;

    return count;

}



inline constexpr std::size_t BufferSize = 1024;



