main()

{

    std::ios::sync_with_stdio(false);



    std::size_t valueCount;

    std::cin >> valueCount;



    std::vector<int> values(valueCount);



    for (std::size_t i = 0; i<valueCount; ++i)

    {

        std::cin >> values[i];

    }



    std::size_t operationCount;

    std::cin >> operationCount;



    std::vector<int> oldValues(operationCount);

    std::vector<int> newValues(operationCount);



    for (std::size_t i = 0; i<operationCount; ++i)

    {

        std::cin >> oldValues[i];

        std::cin >> newValues[i];

    }



    long long sum = 0;

    std::map<int, int> valueCounts;

    for (auto &value : values)

    {

        MapAddCount(valueCounts, value, 1);

        sum += value;

    }



    for (std::size_t i = 0; i<operationCount; ++i)

    {

        auto oldValue = oldValues[i];

