int updata(int pre, int l, int r, int x, int z) {
    int rt = ++cnt;
    sum[rt] = sum[pre] + z;
    lson[rt] = lson[pre], rson[rt] = rson[pre];
    if (l == r) return rt;
    int mid = (l + r) / 2;
    if (x <= mid) lson[rt] = updata(lson[rt], l, mid, x, z);
    else rson[rt] = updata(rson[rt], mid + 1, r, x, z);
    return rt;
}

int query(int rt, int l, int r, int x) {
    if (l == r) return sum[rt];
    int mid = (l + r) / 2;
    if (x <= mid) return query(lson[rt], l, mid, x);
    else return query(rson[rt], mid + 1, r, x);
}

#define S 1, N - 1

