int partition(int A[], int p, int r)

{

	int x = A[r];

	int i = p - 1;

	int j;

	for (j = p; j < r; j++)

	{

		if (A[j] <= x)

		{

			i++;

			swap(A[i], A[j]);

		}

	}

	swap(A[i+1], A[r]);

	return i+1;

}

void swap(int &a, int &b)

{

	int temp = a;

	a = b;

	b = temp;

}

