        return sum;
    }

    ll rsq(int a, int b) {
        return rsq(b) - (a == 1 ? 0 : rsq(a - 1));
    }

    void update(int k, ll v) {
        for (; k < (int)ft.size(); k += LSOne(k)) ft[k] += v;
    }
};

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    ll f[N] = {};
    int n;
    cin >> n;

    vector<ll> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        f[a[i]]++;
    }

    FenwickTree ft(N);

    for (int i = 0; i < n; ++i) {
        ft.update(a[i], a[i]);
    }

    int q;
    cin >> q;

    while (q--) {
        ll b, c;
        cin >> b >> c;

        if (f[b]) {
            ft.update(b, -f[b] * b);
            ft.update(c, f[b] * c);
            f[c] += f[b];
            f[b] = 0;
        }

        cout << ft.rsq(1, N) << endl;
    }

    return 0;
}

