ll fanc(vector<vector<int>> &vs, int m1, int m2, int m3, string s){

	ll ret = 0;

	for(int i : vs.at(m1)){

		auto itr = lower_bound(vs.at(m2).begin(), vs.at(m2).end(), i);

		while(itr != vs.at(m2).end()){

			int diff = *itr - i;

			int count = lower_bound(vs.at(m3).begin(), vs.at(m3).end(), *itr) - vs.at(m3).begin();

			count = vs.at(m3).size() - count;

			char c;

			if(m3 == 2) c = 'B';

			else if(m3 == 1) c = 'G';

			else c = 'R';

			if(*itr+diff < s.size() && s[*itr+diff] == c) count--;

			ret += (ll)count;

			itr++;

		}

		auto itr2 = lower_bound(vs.at(m3).begin(), vs.at(m3).end(), i);

		while(itr2 != vs.at(m3).end()){

			int diff = *itr2 - i;

