		else if(s[i] == 'G') vs.at(1).push_back(i);

		else if(s[i] == 'B') vs.at(2).push_back(i);

	}

	ll ans = 0;

	// cerr << "tst" << endl;

	ans += fanc(vs, 0, 1, 2, s);

	ans += fanc(vs, 2, 0, 1, s);

	ans += fanc(vs, 1, 2, 0, s);

	cout << ans << endl;

	return 0;

}

