	bitset<MAX_VALUES> reversed;

	bits.flip();

	reversed.flip();

	int x, n, t;

	cin >> x >> n;

	if (n == 0) {

		cout << x;

		exit(0);

	}

	for (int i = 0; i < n; i++) {

		cin >> t;

