	}

	if (bits[x]) {

		cout << x;

		exit(0);

	}

	int rV = bits._Find_next(x);

	int lV = MAX_VALUES - 1 - reversed._Find_next(MAX_VALUES - 1 - x);

	int d1 = abs(rV - x);

	int d2 = abs(lV - x);

	if (d1 < d2) {

		cout << rV;

	} else if (d2 < d1) {

		cout << lV;

	} else {

		cout << min(rV, lV);

	}

	return 0;

}

