void init() {
    fill(T, T + MAX, -1);
    fill(used, used + MAX, false);
    for (int i = 0; i < MAX; i++) Edge[i].clear();
    P.clear();
}

double getDis(int p, int q) {
    return sqrt((P[p].x - P[q].x) * (P[p].x - P[q].x) + (P[p].y - P[q].y) * (P[p].y - P[q].y));
}

