const int M=19,N=200005,inf=1e9+3e5;
int n,v,gao,f[1<<M],g[1<<M],x[N],lst[M][N],nxt[M][N],tong[N];
int main(){
	n=read(); v=read(); x[0]=-inf; x[n+1]=inf;
	for(int i=1;i<=n;i++)x[i]=read();
	for(int i=0;;i++){
		int dali=v>>i; gao=i; nxt[i][n+1]=n; lst[i][0]=1;
		for(int j=1;j<=n;j++)if(x[j]-x[j-1]<=dali)lst[i][j]=lst[i][j-1]; else lst[i][j]=j;
		for(int j=n;j;j--)if(x[j+1]-x[j]<=dali)nxt[i][j]=nxt[i][j+1]; else nxt[i][j]=j;
		if((v>>i)==0)break;
	}
	f[0]=0; g[0]=n+1; 
	for(int i=1;i<(1<<gao);i++){
		f[i]=0; g[i]=n+1;
		for(int j=0;j<gao;j++)if(i>>j&1)f[i]=max(f[i],nxt[j+1][f[i^(1<<j)]+1]);
		for(int j=0;j<gao;j++)if(i>>j&1)g[i]=min(g[i],lst[j+1][g[i^(1<<j)]-1]);
	}
	for(int i=0;i<=n+1;i++)tong[i]=-1;
	for(int i=0;i<(1<<gao);i++){
		int l=f[i],r=g[((1<<gao)-1)^i];
		tong[r]=max(tong[r],l);
	}
	for(int i=1;i<=n;i++)tong[i]=max(tong[i],tong[i-1]);
	for(int i=1;i<=n;i++){
		int l=lst[0][i],r=nxt[0][i];
		puts(tong[r+1]>=l-1?"Possible":"Impossible");
	}
}

