#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int inf = 1e9 + 3e5;

int main() {
    int n, v;
    cin >> n >> v;

    vector<int> x(n + 2);
    x[0] = -inf;
    x[n + 1] = inf;
    for (int i = 1; i <= n; i++) {
        cin >> x[i];
    }

    vector<int> lst(n + 2), nxt(n + 2);
    for (int i = 0; ; i++) {
        int dali = v >> i;
        nxt[n + 1] = n;
        lst[0] = 1;
        for (int j = 1; j <= n; j++) {
            if (x[j] - x[j - 1] <= dali) {
                lst[j] = lst[j - 1];
            } else {
                lst[j] = j;
            }
        }
        for (int j = n; j > 0; j--) {
            if (x[j + 1] - x[j] <= dali) {
                nxt[j] = nxt[j + 1];
            } else {
                nxt[j] = j;
            }
        }
        if ((v >> i) == 0) {
            break;
        }
    }

    vector<int> tong(n + 2, -1);
    for (int i = 0; i <= n + 1; i++) {
        tong[i] = -1;
    }

    for (int i = 0; i < (1 << n); i++) {
        int f = 0, g = n + 1;
        for (int j = 0; j < n; j++) {
            if (i & (1 << j)) {
                f = max(f, nxt[f + 1]);
                g = min(g, lst[g - 1]);
            }
        }
        tong[g] = max(tong[g], f);
    }

    for (int i = 1; i <= n; i++) {
        int l = lst[i], r = nxt[i];
        cout << (tong[r + 1] >= l - 1 ? "Possible" : "Impossible") << endl;
    }

    return 0;
}
